import{c as t,Q as a,j as i,m as s}from"./chunks/framework.rWdQudnF.js";const h=JSON.parse('{"title":"补充杂项","description":"","frontmatter":{"title":"补充杂项"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/补充杂项.md","filePath":"综合知识/系统基础/操作系统/补充杂项.md","lastUpdated":null}'),o={name:"综合知识/系统基础/操作系统/补充杂项.md"};function e(d,l,c,r,u,n){return a(),i("div",null,[...l[0]||(l[0]=[s('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] HTTPS vs HTTP</li><li>[ ] 工作流描述工具</li><li>[ ] 数据资产特征</li><li>[ ] 数据库类型</li><li>[ ] Linux 常用命令</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="https-vs-http" tabindex="-1">HTTPS vs HTTP <a class="header-anchor" href="#https-vs-http" aria-label="Permalink to &quot;HTTPS vs HTTP&quot;">​</a></h3><blockquote><p>🎯 一句话结论：HTTPS 使用加密传输，默认端口 443；HTTP 默认端口 80。电子支付类网站<strong>必须使用 HTTPS</strong>。</p></blockquote><h3 id="工作流描述工具" tabindex="-1">工作流描述工具 <a class="header-anchor" href="#工作流描述工具" aria-label="Permalink to &quot;工作流描述工具&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>用例图</strong>不可用来描述工作流。可用的有：活动图、BPMN、Petri-Net。</p></blockquote><p>工作流表示业务过程模型，通常用图形描述。用例图用于描述系统功能需求，不表示业务流程。</p><h3 id="数据资产特征" tabindex="-1">数据资产特征 <a class="header-anchor" href="#数据资产特征" aria-label="Permalink to &quot;数据资产特征&quot;">​</a></h3><blockquote><p>🎯 一句话结论：数据资产四大特征 — <strong>可增值、可共享、可控制、可量化</strong>。</p></blockquote><p>记忆口诀：&quot;增值共享，控制量化&quot;。不可测试、不可维护。</p><h3 id="数据库类型" tabindex="-1">数据库类型 <a class="header-anchor" href="#数据库类型" aria-label="Permalink to &quot;数据库类型&quot;">​</a></h3><blockquote><p>🎯 一句话结论：键值数据库存储键值对；文档数据库存 JSON/XML/BSON（不止纯文本）；早期三大类型是层次式、网络式、关系型。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>存储格式</th><th>备注</th></tr></thead><tbody><tr><td>键值数据库</td><td>键值对集合</td><td>NoSQL</td></tr><tr><td>文档数据库</td><td>JSON/XML/BSON</td><td>⚠️ 不止纯文本</td></tr><tr><td>关系型数据库</td><td>二维表</td><td>—</td></tr></tbody></table><p>早期数据库三种主要类型：<strong>层次式、网络式、关系型</strong>。键值数据库属于 NoSQL，不是早期三大类型。</p><h3 id="linux-常用命令" tabindex="-1">Linux 常用命令 <a class="header-anchor" href="#linux-常用命令" aria-label="Permalink to &quot;Linux 常用命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>功能</th></tr></thead><tbody><tr><td><code>ping</code></td><td>测试主机可达性</td></tr><tr><td><code>ifconfig</code></td><td>查看网络配置</td></tr><tr><td><code>netstat</code></td><td>查看网络状态</td></tr><tr><td><code>uname</code></td><td>查看系统信息</td></tr></tbody></table><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q17] Linux命令</strong></p><p>在Linux系统中，一般用（ ）命令来测试另一台主机是否可达。</p><ul><li>A. ping</li><li>B. ifconfig</li><li>C. netstat</li><li>D. uname</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：ping 测试网络连通性；ifconfig 看网络配置；netstat 看网络状态；uname 看系统信息。</p></div></details><hr><p><strong>[Q34] HTTPS vs HTTP</strong></p><p>以下关于HTTPS和HTTP协议的描述中，不正确的是（ ）。</p><ul><li>A. HTTPS协议使用加密传输</li><li>B. HTTPS协议默认服务端口号是443</li><li>C. HTTP协议默认服务端口是80</li><li>D. 电子支付类网站应使用HTTP协议</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：支付类网站必须用HTTPS加密传输，HTTP明文不安全。</p></div></details><hr><p><strong>[Q35] 工作流</strong></p><p>工作流表示的是业务过程模型，通常使用图形形式来描述，以下不可用来描述工作流的是（ ）。</p><ul><li>A. 活动图</li><li>B. BPMN</li><li>C. 用例图</li><li>D. Petri-Net</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：用例图描述系统功能需求，不描述业务流程。活动图/BPMN/Petri-Net 均可描述工作流。</p></div></details><hr><p><strong>[Q37] 数据资产</strong></p><p>数据资产的特征包括（ ）。①可增值 ②可测试 ③可共享 ④可维护 ⑤可控制 ⑥可量化</p><ul><li>A. ①②③④</li><li>B. ①②③⑤</li><li>C. ①②④⑤</li><li>D. ①③⑤⑥</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：数据资产特征：可增值、可共享、可控制、可量化。不含&quot;可测试&quot;和&quot;可维护&quot;。</p></div></details><hr><p><strong>[Q83] 网络协议</strong></p><p>关于网络协议的描述，下列说法错误的是（ ）。</p><ul><li>A. 是计算机网络通信必须遵循的规则</li><li>B. 规定了数据传送的时序和格式</li><li>C. 只需规定数据格式即可完成通信</li><li>D. 包含控制信息和应答信号的规定</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：网络协议需要规定格式+时序+控制信息+应答信号，缺一不可。</p></div></details><hr><p><strong>[Q90] 文档数据库</strong></p><p>关于文档数据库的特点，下列说法错误的是（ ）。</p><ul><li>A. 可以存储XML格式的文档</li><li>B. 可以存储JSON格式的文档</li><li>C. 只能存储纯文本格式的文档</li><li>D. 可以存储BSON格式的文档</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：文档数据库支持XML/JSON/BSON等多种格式，不是只能存纯文本。</p></div></details><hr><p><strong>[Q91] 键值数据库</strong></p><p>关于键值数据库的特点，下列描述正确的是（ ）。</p><ul><li>A. 数据以二维表形式存储</li><li>B. 数据以列形式存储</li><li>C. 数据以键值对集合形式存储</li><li>D. 数据以文档格式存储</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：键值数据库=key-value对集合；A 是关系型；B 是列存储；D 是文档数据库。</p></div></details><hr><p><strong>[Q92] 早期数据库</strong></p><p>下列选项中，不属于早期数据库三种主要类型的是（ ）。</p><ul><li>A. 层次式数据库</li><li>B. 网络式数据库</li><li>C. 键值数据库</li><li>D. 关系型数据库</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：早期三种：层次、网络、关系型。键值数据库是NoSQL时代的产物。</p></div></details>',57)])])}const m=t(o,[["render",e]]);export{h as __pageData,m as default};
